import { useEffect, useState } from "react";
import { Link, useParams } from "react-router-dom";
import { getCourseById } from "../api/api";
import { Container, Button, Row, Col } from "react-bootstrap";

function SyllabusDetail() {
  const { id } = useParams();
  const [crs, setCrs] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedClassId, setSelectedClassId] = useState(null);
  const [selectedSlotNumber, setSelectedSlotNumber] = useState(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    getCourseById(id)
      .then((data) => {
        if (!cancelled) {
          setCrs(data);
          setError(null);
        }
      })
      .catch(() => {
        if (!cancelled) setError("Không tìm thấy lớp học.");
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [id]);

  const classes = crs?.classes ?? [];

  return (
    <Container className="app-container">
      {loading ? (
        <p className="empty-state">Đang tải dữ liệu...</p>
      ) : error || !crs ? (
        <p className="empty-state">Không tìm thấy khóa học.</p>
      ) : (
        <div className="detail-card">
          <h1>{crs.nameEn}</h1>
        </div>
      )}

      <div>
        {crs && !loading && (
          <div className="student-section">
            {classes.length === 0 ? (
              <p className="empty-state">Chưa có lớp cho môn học này.</p>
            ) : (
              <div>
                <div style = {{display: 'flex'}}><p><strong>{crs.code}</strong> • {selectedClassId}</p></div>
                <div>
                  <Button variant="info">
                    <Link to="/courses" className="back-link">
                      ← Back
                    </Link>
                  </Button>
                  <Button variant="danger">Delete questions</Button>
                  <Button variant="primary">OPEN</Button>
                </div>
                {(() => {
                  const selectedClass = classes.find(
                    (cls) => cls.classId === selectedClassId,
                  );
                  const slots = selectedClass?.slots ?? [];
                  const selectedSlot = slots.find(
                    (slot) => slot.slotNumber === selectedSlotNumber,
                  );

                  return (
                    <Row>
                      <Col md={4}>
                        <h4>Classes</h4>
                        {classes.map((cls) => (
                          <Button
                            key={cls.classId}
                            variant={"info"}
                            style={{ display: "flex" }}
                            onClick={() => {
                              setSelectedClassId(
                                selectedClassId === cls.classId
                                  ? null
                                  : cls.classId,
                              );
                              setSelectedSlotNumber(null);
                            }}
                          >
                            <div
                              style={{
                                width: "10px",
                                height: "10px",
                                borderRadius: "50%",
                                backgroundColor: "green",
                              }}
                            ></div>
                            {cls.classId}
                          </Button>
                        ))}

                        {selectedClassId && (
                          <div>
                            <h4>Slots</h4>
                            {slots.length === 0 ? (
                              <p className="empty-state">Chưa có slot nào.</p>
                            ) : (
                              slots.map((slot) => (
                                <Button
                                  key={slot.slotNumber}
                                  variant="outline-primary"
                                  style={{ display: "flex" }}
                                  onClick={() =>
                                    setSelectedSlotNumber(
                                      selectedSlotNumber === slot.slotNumber
                                        ? null
                                        : slot.slotNumber,
                                    )
                                  }
                                >
                                  {slot.slotNumber} • {slot.date} • {slot.time}
                                </Button>
                              ))
                            )}
                          </div>
                        )}
                      </Col>

                      <Col md={8}>
                        {selectedSlot && (
                          <div style={{ display: "flex", flexDirection: "column" }}>
                            <h4>{selectedSlot.title}</h4>

                            {selectedSlot.assignments && (
                              <div style={{ display: "flex", flexDirection: "column" }}>
                                <strong>Assignments</strong>
                                {selectedSlot.assignments.length === 0 ? (
                                  <p className="empty-state">Không có assignment.</p>
                                ) : (
                                  selectedSlot.assignments.map((a, idx) => (
                                    <p key={idx}>{a}</p>
                                  ))
                                )}
                              </div>
                            )}

                            {selectedSlot.questions && (
                              <div style={{ display: "flex", flexDirection: "column" }}>
                                <strong>Questions</strong>
                                {selectedSlot.questions.length === 0 ? (
                                  <p className="empty-state">Không có question.</p>
                                ) : (
                                  selectedSlot.questions.map((q, idx) => (
                                    <p key={idx}>{q}</p>
                                  ))
                                )}
                              </div>
                            )}

                            {selectedSlot.content && <p>{selectedSlot.content}</p>}
                          </div>
                        )}
                      </Col>
                    </Row>
                  );
                })()}
              </div>
            )}
          </div>
        )}
      </div>
    </Container>
  );
}

export default SyllabusDetail;
